import { createContext, useContext, useState } from "react";
import { useNavigate } from "react-router-dom";

// Dummy Accounts für den Start
const mockUsers = [
  {
    username: "lehrer1",
    password: "test123",
    role: "teacher",
  },
  {
    username: "max",
    password: "passwort",
    role: "student",
    progress: {
      level1: true,
      level2: false,
    },
  },
];

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  const login = (username, password) => {
    const found = mockUsers.find(
      (u) => u.username === username && u.password === password
    );
    if (found) {
      setUser(found);
      if (found.role === "teacher") navigate("/dashboard");
      else if (found.role === "student") navigate("/level1/start"); 
      return true;
    }
    return false;
  };

  const loginAsGuest = () => {
    setUser({ role: "guest" });
    navigate("/play");
  };

  const logout = () => {
    setUser({ role: "guest", username: "Gast" });
    navigate("/login");
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, loginAsGuest }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
